            cargo_version: String::new(),
            command: None,
            tools: Vec::new(),
            risk: None,
            no_autoload: false,
            update_channel: None,
        }
    }

    // ── RED tests ─────────────────────────────────────────────────────────

    #[test]
    fn valid_git_add() {
        let dir = temp_dir();
        let path = dir.join("modules.toml");
        // Write minimal valid modules.toml
        let minimal = r#"
[registry.calibration]
bytes_per_token = 0.813
measured_at = "2025-01-01T00:00:00Z"
"#;
        std::fs::write(&path, minimal).unwrap();

        let args = make_mcp_git_args("foo", "https://github.com/x/y", "abc123", "/run/foo");
        run(&args, &dir).unwrap();

        let content = std::fs::read_to_string(&path).unwrap();
        assert!(content.contains("[module.foo]"));
        assert!(content.contains("git"));
        assert!(content.contains("abc123"));
        assert!(content.contains("kind"));
        assert!(content.contains("/run/foo"));
        assert!(content.contains("autoload = true"));
        assert!(content.contains("risk"));
        assert!(content.contains("context_cost_tokens = 0"));

        // round-trip: load must succeed
        let mf = ModulesFile::load(&path).unwrap();
        assert!(mf.module.contains_key("foo"));
        let m = &mf.module["foo"];
        assert_eq!(m.kind, ModuleKind::Mcp);
        assert!(m.command.is_some());
    }

    #[test]
    fn valid_npm_add() {
        let dir = temp_dir();
        let path = dir.join("modules.toml");
        std::fs::write(&path, r#"
[registry.calibration]
bytes_per_token = 0.813
