        std::fs::write(&path, "# comment\n[module.existing]\nkind = \"mcp\"\nsource = { git = \"https://x/y\", rev = \"abc\" }\ncommand = \"/run\"\n").unwrap();
        run(&git_args("new", "/run/new"), &d).unwrap();
        let c = std::fs::read_to_string(&path).unwrap();
