        assert!(c.contains("[module.existing]"));
        assert!(c.contains("[module.new]"));
        let mf = ModulesFile::load(&path).unwrap();
        assert!(mf.module.contains_key("existing"));
        assert!(mf.module.contains_key("new"));
    }

