        let dir = temp_dir();
        let path = dir.join("modules.toml");
        let existing = r#"# This is a comment
[registry.calibration]
bytes_per_token = 0.813
measured_at = "2025-01-01T00:00:00Z"

[module.polyforge]
kind = "mcp"
source = { git = "https://github.com/example/polyforge", rev = "abc123" }
command = "/run/polyforge"
"#;
        std::fs::write(&path, existing).unwrap();

        let args = make_mcp_git_args("new-mod", "https://github.com/x/y", "def456", "/run/new");
        run(&args, &dir).unwrap();

        let content = std::fs::read_to_string(&path).unwrap();
        // comment preserved
        assert!(content.contains("# This is a comment"));
        // polyforge preserved
        assert!(content.contains("[module.polyforge]"));
        assert!(content.contains("polyforge"));
        // new module appended
        assert!(content.contains("[module.new-mod]"));

        // round-trip
        let mf = ModulesFile::load(&path).unwrap();
        assert!(mf.module.contains_key("polyforge"));
        assert!(mf.module.contains_key("new-mod"));
    }
