    #[test]
    fn tools_with_values() {
        let dir = temp_dir();
        let path = dir.join("modules.toml");
        std::fs::write(&path, r#"
[registry.calibration]
bytes_per_token = 0.813
measured_at = "2025-01-01T00:00:00Z"
"#).unwrap();

        let mut args = make_mcp_git_args("tools-val", "https://github.com/x/y", "abc", "/run/tools");
